mapper.select:
SELECT b.id, b.member_id, b.change_type, b.change_amount, b.before_balance, b.after_balance, b.biz_type, b.biz_id, b.remark, b.operator_id, b.create_time, m.name AS member_name, m.card_no FROM balance_record b LEFT JOIN member m ON m.id = b.member_id
AND b.member_id = #{memberId} AND b.change_type = #{changeType}
ORDER BY b.create_time DESC, b.id DESC
